[CmdletBinding()]
param([ValidateSet('Files','Apps','All')][string]$Mode='All',[string[]]$Target,[string[]]$Exclude,[string]$OutputDir,[int]$UnusedDays=365,[int]$FolderDepth=3,[switch]$IncludeRawLastAccess,[switch]$IncludeRemovable,[switch]$LowerPriority)
$ErrorActionPreference='Stop'
if($ExecutionContext.SessionState.LanguageMode -ne 'FullLanguage'){[Console]::Error.WriteLine('FullLanguage モードが必要です。制約付き言語モードでは実行できません。');exit 2}
if($PSVersionTable.PSVersion.Major -lt 7){[Console]::Error.WriteLine('PowerShell 7 以降が必要です。');exit 2}
$lib=Join-Path $PSScriptRoot 'lib';foreach($f in Get-ChildItem -LiteralPath $lib -Filter '*.ps1'){. $f.FullName}
$configPath=Join-Path (Split-Path $PSScriptRoot -Parent) 'config/config.psd1';$config=@{};if(Test-Path -LiteralPath $configPath){try{$config=Import-PowerShellDataFile -LiteralPath $configPath}catch{Write-Warning "設定ファイルを読み込めません: $($_.Exception.Message)"}}
foreach($key in 'Mode','Target','Exclude','OutputDir','UnusedDays','FolderDepth','IncludeRawLastAccess','IncludeRemovable'){if($PSBoundParameters.ContainsKey($key)){continue};if($config.ContainsKey($key)){Set-Variable -Name $key -Value $config[$key]}}
if(!$Target){$Target=@($env:USERPROFILE,'C:\Program Files','C:\Program Files (x86)')|Where-Object {$_ -and (Test-Path -LiteralPath $_)}}
if(!$OutputDir){$OutputDir=Join-Path $env:LOCALAPPDATA 'WinInspector/Logs'}
$OutputDir=ConvertTo-InspectorPath $OutputDir
if($OutputDir.StartsWith('\\') -or ([IO.DriveInfo]::new([IO.Path]::GetPathRoot($OutputDir)).DriveType -eq [IO.DriveType]::Network)){[Console]::Error.WriteLine('ネットワーク上の出力先は使用できません');exit 2}
if($LowerPriority){try{[Diagnostics.Process]::GetCurrentProcess().PriorityClass=[Diagnostics.ProcessPriorityClass]::BelowNormal}catch{}}
$stamp=Get-Date -Format 'yyyyMMdd-HHmmss';$runDir=Join-Path $OutputDir $stamp
$effectiveExclude=@($Exclude | Where-Object {$_})+@($runDir)
foreach($scanTarget in $Target){try{$normalized=ConvertTo-InspectorPath $scanTarget;if($normalized -match '^[A-Za-z]:\\?$'){$effectiveExclude+=@((Join-Path $normalized '$Recycle.Bin'),(Join-Path $normalized 'System Volume Information'),(Join-Path $normalized 'Windows\WinSxS'))}}catch{}}
try{Assert-NoReparseOutputPath $OutputDir;New-InspectorOutputDirectory $runDir;Assert-NoReparseOutputPath $runDir}catch{[Console]::Error.WriteLine("出力先を作成できません: $($_.Exception.Message)");exit 2}
$startedAt=[DateTime]::UtcNow;$candidateSummary=[Collections.Generic.List[object]]::new();$errors=[Collections.Generic.List[object]]::new();$filesWriter=$null;$foldersWriter=$null;$appsWriter=$null;$candidateWriter=$null;$errorsWriter=$null;$interrupted=$false;$result=$null;$fileCounter=[pscustomobject]@{Count=0};$folderCounter=[pscustomobject]@{Count=0};$networkShortcutCount=0
try{
    $errorsWriter=Open-InspectorCsv $runDir "errors_$stamp.csv" @('Path','Operation','ErrorType','Message')
    $filesCols=@('Path','Type','SizeBytes','CreationTime','LastWriteTime','LastAccessTime','LastAccessStatus','Attributes','Extension');if($IncludeRawLastAccess){$filesCols+=@('LastAccessTime_Raw')}
    if($Mode -in 'Files','All'){$filesWriter=Open-InspectorCsv $runDir "files_$stamp.csv" $filesCols;$foldersWriter=Open-InspectorCsv $runDir "folders_$stamp.csv" @('Path','Depth','DirectSizeBytes','TotalSizeBytes','FileCount','HadErrors')}
    $csvRowWriter=${function:Write-InspectorCsvRow};$onErr={param($p,$op,$type,$msg)$row=[pscustomobject]@{Path=$p;Operation=$op;ErrorType=$type;Message=$msg};$errors.Add($row);if($errorsWriter){Write-InspectorCsvRow $errorsWriter @('Path','Operation','ErrorType','Message') $row @('Path','Message')}};$environment=Get-InspectorEnvironment -OnError $onErr;$tracking=Get-AppTrackingSetting -OnError $onErr
    if($Mode -in 'Files','All'){$scan=Invoke-FileScan -Targets $Target -Exclude $effectiveExclude -OutputDir $runDir -FolderDepth $FolderDepth -IncludeRawLastAccess:$IncludeRawLastAccess -IncludeRemovable:$IncludeRemovable -LastAccessSetting $environment.LastAccess -OnFile {param($row)$fileCounter.Count++;& $csvRowWriter $filesWriter $filesCols $row}.GetNewClosure() -OnFolder {param($row)$folderCounter.Count++;& $csvRowWriter $foldersWriter @('Path','Depth','DirectSizeBytes','TotalSizeBytes','FileCount','HadErrors') $row}.GetNewClosure() -OnError $onErr -OnProgress {param($n,$p,$elapsed)Write-Progress -Activity 'WinInspector ファイル走査' -Status "$n 件 / $($elapsed.ToString()) / $p"}.GetNewClosure()}
    if($Mode -in 'Apps','All'){
        $appsWriter=Open-InspectorCsv $runDir "apps_$stamp.csv" @('Source','Name','Version','Publisher','InstallDate','InstallDateSource','SizeBytes','SizeSource','InstallLocation','LastRunTime','LastRunSource','RunCount','MatchMethod','Status','ExcludedReason')
        $candidateWriter=Open-InspectorCsv $runDir "app_candidates_$stamp.csv" @('Source','Name','Version','Publisher','InstallDate','SizeBytes','InstallLocation','LastRunTime','LastRunSource','RunCount','MatchMethod','Status','ExcludedReason')
        $inventory=@(Get-UninstallInventory -OnError $onErr);$appx=@(Get-AppxInventory -OnError $onErr);$appxError=$appx|Where-Object {$_.Error};$inventory+=@($appx|Where-Object {-not $_.Error})
                $evidence=@(Get-UserAssistEvidence -OnError $onErr);if($environment.IsAdministrator){$evidence+=@(Get-PrefetchEvidence -Enabled -OnError $onErr)}
        $shell=$null;foreach($ev in $evidence){if($ev.Source -eq 'UserAssist' -and $ev.Path -match '\.lnk$'){try{if((Get-ReparsePointAncestor $ev.Path)){$networkShortcutCount++;continue};if(!$shell){$shell=New-Object -ComObject WScript.Shell};$shortcut=$shell.CreateShortcut($ev.Path);$targetPath=[string]$shortcut.TargetPath;if($targetPath.StartsWith('\\') -or (($targetPath -match '^[A-Za-z]:') -and [IO.DriveInfo]::new([IO.Path]::GetPathRoot($targetPath)).DriveType -eq [IO.DriveType]::Network)){$networkShortcutCount++}else{$ev|Add-Member TargetPath $targetPath -Force}}catch{}}};if($shell){try{[void][Runtime.InteropServices.Marshal]::ReleaseComObject($shell)}catch{}}
        $excludeConfig=Join-Path (Split-Path $PSScriptRoot -Parent) 'config/exclusions.psd1';$patterns=@();if(Test-Path $excludeConfig){$patterns=(Import-PowerShellDataFile $excludeConfig).NamePatterns}
        $locationCounts=@{};foreach($group in @($inventory|Where-Object {$_.InstallLocation}|Group-Object {ConvertTo-NormalizedPath $_.InstallLocation})){$locationCounts[$group.Name]=$group.Count}
        foreach($app in $inventory){try{$sizeBytes=$null;$sizeSource='';if($app.EstimatedSize){$sizeBytes=[long]$app.EstimatedSize*1KB;$sizeSource='EstimatedSize'}elseif($app.InstallLocation){$fullLoc=ConvertTo-InspectorPath $app.InstallLocation;$rootPath=[IO.Path]::GetPathRoot($fullLoc).TrimEnd('\');$protected=@($rootPath,(Join-Path $rootPath 'Program Files'),(Join-Path $rootPath 'Program Files (x86)'));if(($protected|Where-Object {[string]::Equals((ConvertTo-NormalizedPath $_),(ConvertTo-NormalizedPath $fullLoc),[StringComparison]::OrdinalIgnoreCase)}) -or $locationCounts[(ConvertTo-NormalizedPath $fullLoc)] -gt 1){$sizeBytes=$null;$sizeSource=''}else{try{$sizeBytes=Measure-InstallFolder $app.InstallLocation -OnError $onErr;if($null -ne $sizeBytes){$sizeSource='FolderSum'}}catch{$onErr.Invoke($app.InstallLocation,'MeasureInstallFolder',$_.Exception.GetType().Name,$_.Exception.Message)}}};$last=$null;$runs=$null;$method='';$loc=[string]$app.InstallLocation;$resolved=Resolve-AppEvidence $app $evidence;$match=$resolved;if($match){$method=$match.Method;$last=$match.Evidence.LastRunTime;$runs=$match.Evidence.RunCount}
            $candidate=[pscustomobject]@{Source=$app.Source;Name=$app.DisplayName ?? $app.Name;Version=$app.DisplayVersion ?? $app.Version;Publisher=$app.Publisher;InstallDate=$app.InstallDate;InstallDateSource=if($app.InstallDate){'Registry'}else{''};SizeBytes=$sizeBytes;SizeSource=$sizeSource;InstallLocation=$loc;LastRunTime=if($last){$last.ToString('yyyy-MM-dd HH:mm:ss')}else{''};LastRunSource=if($match){$match.Evidence.Source}else{'なし'};RunCount=$runs;MatchMethod=$method;CountOnly=if($match){$match.Evidence.CountOnly}else{$false}}
            $class=Get-AppClassification ([pscustomobject]@{Name=$candidate.Name;SystemComponent=$app.SystemComponent;ParentKeyName=$app.ParentKeyName;ReleaseType=$app.ReleaseType;Source=$app.Source;SignatureKind=$app.SignatureKind;IsFramework=$app.IsFramework;NonRemovable=$app.NonRemovable;IsResourcePackage=$app.IsResourcePackage;InstallDate=$candidate.InstallDate;LastRunTime=$last;RunCount=$runs;CountOnly=($match -and $match.Evidence.CountOnly)}) (Get-Date) $UnusedDays $tracking.Enabled $patterns;$candidate|Add-Member Status $class.Status;$candidate|Add-Member ExcludedReason $class.ExcludedReason
            Write-InspectorCsvRow $appsWriter @('Source','Name','Version','Publisher','InstallDate','InstallDateSource','SizeBytes','SizeSource','InstallLocation','LastRunTime','LastRunSource','RunCount','MatchMethod','Status','ExcludedReason') $candidate @('Name','Version','Publisher','InstallDate','InstallDateSource','InstallLocation','LastRunSource','MatchMethod','Status','ExcludedReason')
            if($class.Status -in '候補A','候補B'){$candidateSummary.Add($candidate)}
        }catch{$onErr.Invoke([string]$app.InstallLocation,'ProcessApp',$_.Exception.GetType().Name,$_.Exception.Message)}}
        foreach($status in '候補A','候補B'){$candidateSummary|Where-Object Status -eq $status|Sort-Object @{Expression={if($null -eq $_.SizeBytes){1}else{0}}},@{Expression='SizeBytes';Descending=$true}|ForEach-Object {Write-InspectorCsvRow $candidateWriter @('Source','Name','Version','Publisher','InstallDate','SizeBytes','InstallLocation','LastRunTime','LastRunSource','RunCount','MatchMethod','Status','ExcludedReason') $_ @('Name','Version','Publisher','InstallDate','InstallDateSource','InstallLocation','LastRunSource','MatchMethod','Status','ExcludedReason')}}
    }
}catch [System.Management.Automation.PipelineStoppedException]{$interrupted=$true}catch [System.OperationCanceledException]{$interrupted=$true}catch{$onErr.Invoke('','Main',$_.Exception.GetType().Name,$_.Exception.Message)}finally{
    foreach($w in @($filesWriter,$foldersWriter,$appsWriter,$candidateWriter,$errorsWriter)){if($w){try{$w.Flush();$w.Dispose()}catch{}}};Write-Progress -Activity 'WinInspector ファイル走査' -Completed
}
$accountName='不明';try{$accountName=[Security.Principal.WindowsIdentity]::GetCurrent().Name}catch{}
$topA='未実行';$topB='未実行';if($Mode -in 'Apps','All'){$topA=@($candidateSummary|Where-Object Status -eq '候補A'|Sort-Object SizeBytes -Descending|Select-Object -First 10|ForEach-Object {"$($_.Name) ($($_.SizeBytes) bytes)"}) -join '; ';$topB=@($candidateSummary|Where-Object Status -eq '候補B'|Sort-Object SizeBytes -Descending|Select-Object -First 10|ForEach-Object {"$($_.Name) ($($_.SizeBytes) bytes)"}) -join '; '}
$fileCountSummary=if($Mode -in 'Files','All'){$fileCounter.Count}else{'未実行'};$folderCountSummary=if($Mode -in 'Files','All'){$folderCounter.Count}else{'未実行'}
$summary=@("WinInspector summary","実行日時: $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')","PowerShell: $($environment.PowerShellVersion)","モード: $Mode","対象: $($Target -join '; ')","出力先: $runDir","管理者: $($environment.IsAdministrator)","実行アカウント: $accountName","言語モード: $($environment.LanguageMode)","最終アクセス設定: $($environment.LastAccess.Status) ($($environment.LastAccess.Value))","タイムゾーン: $($environment.TimeZone)","アプリ起動追跡(Start_TrackProgs): $($tracking.Status) / $($tracking.Value)","ファイル件数: $fileCountSummary","フォルダ件数: $folderCountSummary","所要時間: $([DateTime]::UtcNow.Subtract($startedAt))","候補A 上位: $topA","候補B 上位: $topB","エラー件数: $($errors.Count)","Appx取得状態: $(if($appxError){'取得失敗（errors に記録）'}elseif($Mode -in 'Apps','All'){'取得済み'}else{'未実行'})","状態: $(if($interrupted){"中断（$($fileCounter.Count) 件まで）"}elseif($errors.Count){'一部エラー'}else{'完了'})","","設定: 未使用閾値=$UnusedDays 日、FolderDepth=$FolderDepth、Exclude=$($Exclude -join '; ')、Prefetch使用=$(if(($Mode -in @('Apps','All')) -and $environment.IsAdministrator){'はい'}else{'いいえ'})、最終アクセスレジストリ=$($environment.LastAccessRegistryStatus)","制約: UserAssist は現在のユーザーの Explorer 経由の起動のみ記録します。追跡設定が無効なら履歴は残りません。OS 再インストールで履歴は消えます。Prefetch 名は29文字で切り詰められる場合があります。msiexec.exe、update.exe、setup.exe、uninstall*.exe、unins*.exe、install*.exe は Prefetch 照合から除外しています。ネットワーク先またはリンク経由のショートカット：$networkShortcutCount 件は読み取りませんでした。共有・巨大な InstallLocation の FolderSum は安全のため省略しています。未変換の GUID 付きパス：$(@($evidence | Where-Object {$_.Path -match '\{[0-9A-Fa-f-]{36}\}\\'}).Count)件。","最終アクセス時刻は有効な NTFS 設定の場合のみ記録し、最大1時間程度の精度です。セキュリティ製品等でも更新され、ユーザー利用を示すものではありません。設定変更は再起動後に反映されます。","ハードリンクは区別できず二重計上される場合があります。ファイル列挙時点のメタデータは開いているファイルで実体とずれる場合があります.") -join "`r`n"
try{Write-InspectorText $runDir "summary_$stamp.txt" $summary}catch{[Console]::Error.WriteLine("summary を書き込めません: $($_.Exception.Message)")}
Write-Host "出力先: $runDir"
